"""Freeze physical bus/clock proof before deleting only verified generated files."""
import gzip
import hashlib
import json
import subprocess
import sys
from actor_reference import ROOT


def sha(raw):return hashlib.sha256(raw).hexdigest()


def main():
    out=ROOT/'analysis/md-io-clock-v0203';assert not out.exists(),'Immutable archive exists'
    folder=ROOT/'validation/md-io-clock';report=json.loads((ROOT/'analysis/md_io_clock_report.json').read_text())
    assert report['host']['checks']==885105
    for name,h in report['clock_sources'].items():assert sha((ROOT/'megadrive/src'/name).read_bytes())==h
    assert sha((folder/'out/release/rom.bin').read_bytes())==report['kernel_sha256']
    core=ROOT.parents[1]/'work/genesis-plus-gx'
    assert sha((core/'genesis_plus_gx_io_libretro.dll').read_bytes())==report['observer_core_sha256']
    for name in ['mem68k.c','vdp_ctrl.c']:
        assert sha((core/'core'/name).read_bytes())==(folder/(name+'-original.sha256')).read_text().strip()
    for result in report['results']:
        assert result['done'] and not result['failures'] and result['samples']==8192 and result['burst_writes']==3072 and result['plain_core_identical']
        assert sha((folder/(result['region']+'-events.json')).read_bytes())==result['events_sha256']
    playable=sha((ROOT/'gaw-megadrive.bin').read_bytes())
    assert playable=='7660a4b5949d0f3362c4795ed5eb238f86c289708b51d1dda6eec669b4d3ecb7'
    paths={ROOT/'README.md',ROOT/'analysis/md_io_clock_milestone.md',ROOT/'analysis/md_io_clock_report.json'}
    paths.update(ROOT/'tools'/name for name in ['build_md_io_core.py','validate_md_io_clock.py','archive_md_io_clock.py'])
    paths.update(ROOT/'megadrive/src'/name for name in report['clock_sources'])
    paths.update(p for p in folder.rglob('*') if p.is_file())
    sources={p.relative_to(ROOT).as_posix():p for p in paths}
    sources['emulator/genesis_plus_gx_io_libretro.dll']=core/'genesis_plus_gx_io_libretro.dll'
    sources['emulator/hvc.h']=core/'core/hvc.h'
    files={};compressed={};candidates=[]
    for name,p in sorted(sources.items()):
        raw=p.read_bytes();h=sha(raw)
        if p.is_relative_to(folder) or len(raw)>65536 or name.startswith('emulator/'):
            blob='objects/'+h+'.gz';dest=out/blob;dest.parent.mkdir(parents=True,exist_ok=True)
            if not dest.exists():dest.write_bytes(gzip.compress(raw,mtime=0))
            assert gzip.decompress(dest.read_bytes())==raw
            compressed[name]=dict(stored=blob,raw_sha256=h,raw_bytes=len(raw),stored_sha256=sha(dest.read_bytes()))
            if p.is_relative_to(folder) and (p.suffix in ['.bin','.out','.o','.s','.d','.dll'] or p.name.endswith('-events.json') or p.name.endswith('-diagnostic.json')):candidates.append(p)
        else:
            dest=out/name;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_bytes(raw);files[name]=h
    data=dict(playable_sha256=playable,physical_deadline_pacing=False,files=files,compressed=compressed,removed_verified_generated=[])
    manifest=out/'manifest.json';manifest.write_text(json.dumps(data,indent=2)+'\n')
    if '--cleanup' in sys.argv:
        for p in candidates:
            target=p.resolve();assert target.is_relative_to(folder.resolve())
            name=target.relative_to(ROOT).as_posix();assert not subprocess.check_output(['git','ls-files','--',name],cwd=ROOT)
            item=compressed[name];raw=target.read_bytes();assert sha(raw)==item['raw_sha256'] and gzip.decompress((out/item['stored']).read_bytes())==raw
            data['removed_verified_generated'].append(dict(path=name,bytes=len(raw)));target.unlink()
        manifest.write_text(json.dumps(data,indent=2)+'\n')
    print(len(files),'snapshots;',len(compressed),'compressed references;',sum(v['bytes'] for v in data['removed_verified_generated']),'generated bytes removed')


if __name__=='__main__':main()
